// Peso sin comprimir de audio y video: cambiá los valores y mirá qué variable manda
const fmt = (n) => n.toLocaleString("es-AR", { maximumFractionDigits: 2 });

function audio(hz, bits, canales, segundos) {
  const bitrate = hz * bits * canales;            // bit/s
  return { bitrate, bytes: (bitrate * segundos) / 8 };
}
function video(ancho, alto, fps, segundos) {
  const bytesCuadro = ancho * alto * 3;           // 3 bytes por píxel (RGB)
  const bitrate = bytesCuadro * fps * 8;           // bit/s
  return { bitrate, bytes: (bytesCuadro * fps * segundos) };
}

const cd = audio(44100, 16, 2, 60);
console.log(`CD, 1 min: ${fmt(cd.bitrate / 1000)} kbit/s, ${fmt(cd.bytes / 1e6)} MB`);

const mp3 = (128000 * 60) / 8;
console.log(`MP3 a 128 kbit/s, 1 min: ${fmt(mp3 / 1e6)} MB (${fmt(cd.bytes / mp3)} veces menos)`);

const v = video(1920, 1080, 30, 60);
console.log(`Full HD 30 fps, 1 min: ${fmt(v.bitrate / 1e9)} Gbit/s, ${fmt(v.bytes / 1e9)} GB`);

const yt = (8e6 * 60) / 8;
console.log(`Mismo minuto a 8 Mbit/s: ${fmt(yt / 1e6)} MB (${fmt(v.bytes / yt)} veces menos)`);

// Aliasing: dónde reaparece un tono que supera la mitad del muestreo
const fs = 44100;
for (const f of [10000, 20000, 25000, 30000]) {
  const alias = f <= fs / 2 ? f : Math.abs(f - fs);
  console.log(`tono de ${f} Hz muestreado a ${fs} Hz se oye como ${alias} Hz`);
}
